<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientBackchannelLogoutSessionRequiredAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientBackchannelLogoutSessionRequiredAccessor trait.
 *
 * Covers null default, string/VO assignment via withBackchannelLogoutSessionRequired,
 * getBackchannelLogoutSessionRequired/backchannelLogoutSessionRequired accessors, and isBackchannelLogoutSessionRequiredChanged with/without original.
 */
class TrustedClientBackchannelLogoutSessionRequiredAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withBackchannelLogoutSessionRequired creates a new instance with the BackchannelLogoutSessionRequired set
     * from a string value, and getBackchannelLogoutSessionRequired returns the primitive string.
     */
    public function testWithBackchannelLogoutSessionRequiredFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelLogoutSessionRequiredAccessorUnitTest();

        // Act
        $result = $holder->withBackchannelLogoutSessionRequired(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isBackchannelLogoutSessionRequired());
    }
    /**
     * Asserts that withbackchannelLogoutSessionRequired has access to the value object
     * from a string value, and getBackchannelLogoutSessionRequired returns the primitive string.
     */
    public function testWithBackchannelLogoutSessionRequiredFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelLogoutSessionRequiredAccessorUnitTest();

        // Act
        $result = $holder->withBackchannelLogoutSessionRequired(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->backchannelLogoutSessionRequired()->value());
    }
    public function testChangedBackchannelLogoutSessionRequired(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackchannelLogoutSessionRequiredAccessorUnitTest();
        $original = $holder->withBackchannelLogoutSessionRequired(true);
        $same = $holder->withBackchannelLogoutSessionRequired(true);
        $modified = $holder->withBackchannelLogoutSessionRequired(false);

        // Act
        $unchanged = $holder->isBackchannelLogoutSessionRequiredChanged();
        $withSame = $original->isBackchannelLogoutSessionRequiredChanged($same);
        $withDiferent = $original->isBackchannelLogoutSessionRequiredChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientBackchannelLogoutSessionRequiredAccessorUnitTest
{
    use TrustedClientBackchannelLogoutSessionRequiredAccessor;
}
